def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    for r in range(h):
        for c in range(w):
            if g[r][c]==1:g[r][c]=2
    sr,sc=next((r,c) for r in range(h) for c in range(w) if g[r][c]==3)
    lines=[]
    for r in range(h):
        cs=[c for c in range(w) if g[r][c]==2]
        if cs:lines.append((r,min(cs),max(cs)))
    def seg(r0,c0,r1,c1):
        if r0==r1:
            for c in range(min(c0,c1),max(c0,c1)+1):g[r0][c]=3
        else:
            for r in range(min(r0,r1),max(r0,r1)+1):g[r][c0]=3
    fr,a,b=lines[0]
    dl,dr=sc-a,b-sc
    direction=-1 if dl<=dr else 1
    d=min(dl,dr); R=fr-sr
    r,c=sr,sc
    if d<R:
        nr=r+d; seg(r,c,nr,c);r=nr
        nc=c+direction*R;seg(r,c,r,nc);c=nc
    else:
        nr=max(sr,fr-2);seg(r,c,nr,c);r=nr
        nc=(a-2 if direction<0 else b+2);seg(r,c,r,nc);c=nc
    if len(lines)==1:seg(0,c,h-1,c)
    for k in range(len(lines)-1):
        direction*=-1
        nr=(lines[k][0]+lines[k+1][0])//2
        seg(r,c,nr,c);r=nr
        length=min(lines[k][2]-lines[k][1]+1,lines[k+1][2]-lines[k+1][1]+1)
        nc=c+direction*length;seg(r,c,r,nc);c=nc
    seg(r,c,h-1,c)
    return g
